"use client";
import type { Metadata } from "next";
import "../globals.css";
import "../style.css";
import Header from "@/components/layout/header/Header";
import Footer from "@/components/layout/footer/Footer";
import { useParams, usePathname } from "next/navigation";
import { Suspense } from "react";
import Loading from "./loading";

// Font: Inter is provided via @font-face in globals.css (no build-time fetch from Google).

// export const metadata: Metadata = {
//   title: "Create Next App",
//   description: "Generated by create next app",
// };

export default function HomeLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const params = useParams();
  const pathname = usePathname();

  const checkCurrentPath = (node: React.ReactNode) => {
    return pathname.startsWith(`/course_detail/${params.id}/contents`)
      ? null
      : node;
  };

  return (
    <>
      <Suspense fallback={<Loading />}>
        {checkCurrentPath(
          <Header title="Home" underlined="HomePage" activeTab="courses" />
        )}
        <div className="min-h-[600px]">
        {children}
        </div>
        
        {checkCurrentPath(<Footer />)}
      </Suspense>
    </>
  );
}
